        d.mkdir(exist_ok=True)
        (d / "gates.tsv").write_text(status + "\tcheck\t1\tfixture.log\tcheck --flag\n")
        if head is True:
            (d / "HEAD").write_text(self.head + "\n")
        elif head:
            (d / "HEAD").write_text(head + "\n")
        return d

